Lemma ms_schunk : forall (m : mem),
  shdr m P msz (needed2 n) (Z.of_nat (length (sec Σ))) -> stk asegs m P (P + msz) -> stk asegs m (shad P) (shad (P + msz)) ->
  ahdr m (P + 4096 + 2032) n -> lch m (P + 4096) (P + 4096 + 2032) ->
  bytes_at asegs m (shad P) (farun 512) -> bytes_at asegs m (shad (P + 4096)) (farun (2048 / 8)) ->
  bytes_at asegs m (shad (P + 4096 + 2048)) (ushadow n) ->
  bytes_at asegs m (shad (P + 4096 + 2048 + ru8 n)) (farun ((smsz n - 4096 - 2048 - ru8 n) / 8)) ->
  schunk (length (sec Σ)) (sec_new P n) m.
Proof using Hn HA HG.
