Theorem mal_sec_ART : forall (m : mem),
  munch W mA m -> wmono asegs mA m -> vis_rep L (shw P n :: rtA_allow Σ) mA ->
  shdr m P msz (needed2 n) (Z.of_nat (length (sec Σ))) -> stk asegs m P (P + msz) -> stk asegs m (shad P) (shad (P + msz)) ->
  ahdr m (P + 4096 + 2032) n -> lch m (P + 4096) (P + 4096 + 2032) ->
  bytes_at asegs m (shad P) (farun 512) -> bytes_at asegs m (shad (P + 4096)) (farun (2048 / 8)) ->
  bytes_at asegs m (shad (P + 4096 + 2048)) (ushadow n) ->
  bytes_at asegs m (shad (P + 4096 + 2048 + ru8 n)) (farun ((smsz n - 4096 - 2048 - ru8 n) / 8)) ->
  sec_core m PAB 0x4000 (Z.of_nat (length (sec Σ)) + 1) -> sec_pad m -> sec_junk m ->
  (exists ws, u64arr asegs m PAB ws /\ Z.of_nat (length ws) = 0x4000
              /\ firstn (length (sec Σ) + 1) ws = map (fun s => Z_to_bv 64 (s_mb s)) (sec Σ ++ [sec_new P n])) ->
  depot_rep D' (DEP_BK (hash_of (d_hs (dep Σ)) 1)) DNB SSB m -> hash_of (d_hs D') 1 = hash_of (d_hs (dep Σ)) 1 ->
  ART_A Σk m.
Proof using Hn HA HG LOW LOR SPT WF.
